<?php
require_once __DIR__ . '/../../includes/db.php';require_once __DIR__ . '/../includes/auth.php';require_login();
if(!isset($_GET['car_id'])||!is_numeric($_GET['car_id'])){redirect_to('backend/cars/list.php');}$car_id=(int)$_GET['car_id'];$car_stmt=$conn->prepare('SELECT id,car_name,plate_number,chassis_number,status FROM cars WHERE id=?');$car_stmt->bind_param('i',$car_id);$car_stmt->execute();$car=$car_stmt->get_result()->fetch_assoc();if(!$car){set_flash('error','Car not found.');redirect_to('backend/cars/list.php');}$costs_stmt=$conn->prepare('SELECT cost_type,description,amount,cost_date FROM car_costs WHERE car_id=? ORDER BY cost_date DESC');$costs_stmt->bind_param('i',$car_id);$costs_stmt->execute();$costs=$costs_stmt->get_result()->fetch_all(MYSQLI_ASSOC);$total_stmt=$conn->prepare('SELECT IFNULL(SUM(amount),0) total_cost FROM car_costs WHERE car_id=?');$total_stmt->bind_param('i',$car_id);$total_stmt->execute();$total=$total_stmt->get_result()->fetch_assoc();
$page_title='Car Costs';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/leftsidebar.php';
?>
<div class="content-page"><div class="report-title"><h1 class="page-title">Car Costs</h1><div><?php if(($car['status'] ?? '')==='IN_STOCK'):?><a class="btn btn-green" href="cost.php?car_id=<?=$car_id?>">Add Cost</a><?php endif;?><a class="btn btn-dark" href="../cars/view.php?id=<?=$car_id?>">Back to Car</a></div></div><div class="card"><p><strong>Name:</strong> <?=e($car['car_name'])?></p><p><strong>Plate:</strong> <?=e(car_sales_plate_label($car['plate_number']))?></p><p><strong>Chassis:</strong> <?=e($car['chassis_number'])?></p><p><strong>Total Cost:</strong> <?=money($total['total_cost'])?></p></div><div class="card"><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Type</th><th>Description</th><th>Amount</th></tr></thead><tbody><?php if($costs): foreach($costs as $cost):?><tr><td><?=e($cost['cost_date'])?></td><td><?=e($cost['cost_type'])?></td><td><?=e($cost['description'] ?: '—')?></td><td><?=money($cost['amount'])?></td></tr><?php endforeach; else: ?><tr><td colspan="4">No costs recorded.</td></tr><?php endif;?></tbody></table></div></div></div><?php include __DIR__.'/../includes/footer.php'; ?>
